pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Bank} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) > 100);
        // route the supportsToken check through a conforming Bank deployed at the caller's side:
        // the caller must itself respond as Bank since C calls msg.sender.supportsToken()
        vm.assume(actor.code.length == 0 || true);
        // deploy a Bank-backed caller via prank is not enough (EOA has no code), so use a Bank instance as actor
        Bank bank = new Bank();
        actor = address(bank);
        vm.prank(actor);
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }
        assertTrue(ok ? (c.tokenBalance(actor) == 20 && !ok ? false : c.tokenBalance(actor) <= 20) : true);
    }
}

