pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 seed) public {
        vm.assume(caller != address(0));
        // drive the interaction through a helper contract that satisfies the supportsToken check
        Bank callerBank = new Bank();
        // first airdrop must succeed for any admissible caller
        vm.prank(address(callerBank));
        bool ok1;
        try c.airDrop() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1 && c.tokenBalance(address(callerBank)) == 20);

        // a second airdrop must always revert: balance capped at 20
