pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 numCalls) public {
        numCalls = uint8(bound(numCalls, 2, 20));
        // airDrop's supportsToken modifier requires Bank(msg.sender).supportsToken()
        // to return keccak256("Nu Token"), so the caller must be a contract
        // impersonating the Bank. Deploy a minimal helper embodying that
        // counterparty and drive airDrop through it, repeating it numCalls times.
        BankCaller caller = new BankCaller();
        for (uint256 i = 0; i < numCalls; i++) {
            caller.tryAirDrop(c);
        }
        // Reference: balance can only ever be 20 (a second airDrop reverts via
        // hasNoBalance). Mutant: repeated calls succeed and balance grows to 40+.
        assertTrue(c.tokenBalance(address(caller)) <= 20);
    }
}

contract BankCaller {
    function tryAirDrop(C c) external {
        try c.airDrop() {} catch {}
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

