pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // The caller of airDrop must satisfy the supportsToken modifier: msg.sender must
        // respond like a Bank. Use a fresh helper per fuzzed seed (fresh address each run).
        Caller caller = new Caller();
        // Drive c.airDrop through the helper (which satisfies supportsToken and has no balance).
        bool ok;
        try caller.go(c) returns (uint256 bal) {
            ok = true;
            // General rule: a successful airDrop credits exactly 20 tokens to the caller.
            assertTrue(bal == 20, "airDrop must credit exactly 20 tokens");
        } catch {
            ok = false;
            assertTrue(!ok, "unexpected revert");
        }
    }
}

// Minimal adversarial counterparty: acts as the airDrop caller, must satisfy the
// supportsToken modifier (msg.sender must be a Bank) so c accepts the call.
contract Caller {
    function go(C c) external returns (uint256) {
        c.airDrop();
        return c.tokenBalance(address(this));
    }

    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

