pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bool reenter, uint256 seed) public {
        // Admissibility: the caller must be a Bank-like contract (supportsToken returns the
        // expected hash); the fuzzer chooses whether it is adversarial (reentrant) or not.
        Attacker attacker = new Attacker(c, reenter);

        attacker.go();

        // General rule: a completed airDrop credits the caller exactly 20 tokens, never more,
        // because _nonReentrant forbids reentry during the supportsToken external call.
        assertTrue(c.tokenBalance(address(attacker)) == 20, "balance must be exactly 20 after one airDrop");
    }
}

contract Attacker {
    C public immutable c;
    bool public immutable reenter;
    bool public entered;

    constructor(C _c, bool _reenter) { c = _c; reenter = _reenter; }

    function go() external {
        c.airDrop();
    }

    function supportsToken() external returns (bytes32) {
        // Reenter exactly once during the outer call's supportsToken hook.
        if (reenter && !entered) {
            entered = true;
            c.airDrop();
        }
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
